using System;
using System.IO;
using UnityEngine;
using UnityEditor;
using UnityEngine.Rendering;
using UnityEngine.Experimental.Rendering;
internal class CommandScript : IRunCommand {
 public void Execute(ExecutionResult result) {
  var shader=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<ComputeShader>("Packages/com.vivid.render-pipelines/Shaders/Core/Private/CSMShadowResolve.compute"));
  const int w=33,h=25;var depth=new Texture2D(w,h,TextureFormat.RFloat,false,true);var normal=new Texture2D(w,h,TextureFormat.RGBAFloat,false,true);var src=new Texture2D(w,h,TextureFormat.RFloat,false,true);
  var a=new RenderTexture(new RenderTextureDescriptor(w,h,GraphicsFormat.R16_SFloat,0){enableRandomWrite=true});var b=new RenderTexture(a.descriptor);a.Create();b.Create();var cmd=new CommandBuffer();string report="";
  try {
   for(int test=0;test<4;test++) {
    float[] depths=new float[w*h],values=new float[w*h];Color[] normals=new Color[w*h];
    for(int y=0;y<h;y++)for(int x=0;x<w;x++){int i=y*w+x;depths[i]=test==2&&x>=16?.0001f:.5f;values[i]=test==0?.375f:test==1?((x+y)%2):x<16?0:1;normals[i]=test==3&&x>=16?new Color(1,1,0,0):new Color(.5f,.5f,0,0);}
    depth.SetPixelData(depths,0);depth.Apply();src.SetPixelData(values,0);src.Apply();normal.SetPixels(normals);normal.Apply();
    cmd.Clear();cmd.SetComputeIntParam(shader,"_CSMOutputWidth",w);cmd.SetComputeIntParam(shader,"_CSMOutputHeight",h);
    cmd.SetComputeVectorParam(shader,"_ZBufferParams",new Vector4(0,0,3.3323333f,.001f));
    foreach(string kernel in new[]{"VSMShadowBilateralFilterH","VSMShadowBilateralFilterV"}) {
     int k=shader.FindKernel(kernel);bool horizontal=kernel.EndsWith("H");cmd.SetComputeTextureParam(shader,k,"_DepthTexture",depth);cmd.SetComputeTextureParam(shader,k,"_GBuffer1",normal);cmd.SetComputeTextureParam(shader,k,"_CSMShadowFilterSource",horizontal?(Texture)src:a);cmd.SetComputeTextureParam(shader,k,"_CSMShadowFilterTexture",horizontal?a:b);cmd.DispatchCompute(shader,k,(w+7)/8,(h+7)/8,1);
    }
    Graphics.ExecuteCommandBuffer(cmd);var r=AsyncGPUReadback.Request(b,0,TextureFormat.RFloat);r.WaitForCompletion();if(r.hasError)throw new Exception("GPU readback");var output=r.GetData<float>();double maxError=0,mean=0;for(int i=0;i<w*h;i++){float expected=test==1?.5f:values[i];if(test==1&&(i%w<4||i%w>=w-4||i/w<4||i/w>=h-4))continue;maxError=Math.Max(maxError,Math.Abs(output[i]-expected));mean+=output[i];}
    report+="case="+test+" maxError="+maxError+" meanSum="+mean+"\n";if(maxError>(test==1?.005:.001))throw new Exception(report);
   }
   File.WriteAllText("Packages/VividRP/Temp~/vsm-correctness/filter-gpu.txt",report+"passed=4");result.Log(report+"passed=4");
  } finally {cmd.Dispose();UnityEngine.Object.DestroyImmediate(shader);UnityEngine.Object.DestroyImmediate(depth);UnityEngine.Object.DestroyImmediate(normal);UnityEngine.Object.DestroyImmediate(src);UnityEngine.Object.DestroyImmediate(a);UnityEngine.Object.DestroyImmediate(b);}
 }
}
